import {lines,stations,timeLabel,shanghaiMinute} from './network.mjs';
import {data,directionInfo,todayShanghai,extended,dateShift,serviceTime} from './schedule.mjs';
const $=id=>document.getElementById(id);let minute=shanghaiMinute(),date=todayShanghai(),live=true,playing=false,zoom=.75,night=false;const ns='http://www.w3.org/2000/svg';
function el(tag,attrs,parent=$('map')){const n=document.createElementNS(ns,tag);for(const [k,v]of Object.entries(attrs))n.setAttribute(k,v);parent.append(n);return n;}
function point(l,i){return l.id==='1'?[710,1126-i*38]:[110+i*50,670];}
const edges=[],nodes=new Map();
for(const l of lines){for(let i=0;i<l.names.length-1;i++){for(const d of [1,-1]){const source=d===1?i:i+1,target=d===1?i+1:i;const a=point(l,source),b=point(l,target),dx=b[0]-a[0],dy=b[1]-a[1],len=Math.hypot(dx,dy),ox=-dy/len*6,oy=dx/len*6;const g=el('g',{'data-line':l.id,'data-from':l.names[source],'data-direction':d});const path=el('path',{d:`M${a[0]+ox},${a[1]+oy}L${b[0]+ox},${b[1]+oy}`,stroke:l.color,'stroke-width':5},g);const mx=(a[0]+b[0])/2+ox,my=(a[1]+b[1])/2+oy,ux=dx/len,uy=dy/len;const arrow=el('path',{d:`M${mx-ux*4-uy*3},${my-uy*4+ux*3}L${mx+ux*3},${my+uy*3}L${mx-ux*4+uy*3},${my-uy*4-ux*3}`,fill:'none',stroke:l.color,'stroke-width':2},g);edges.push({g,path,arrow,l,source,d});}}
for(let i=0;i<l.names.length;i++){const name=l.names[i];if(nodes.has(name))continue;const [x,y]=point(l,i);const g=el('g',{class:'stop',tabindex:0,role:'button','aria-label':`查看${name}`});const circle=el('circle',{cx:x,cy:y,r:name==='人民广场'?10:5,fill:'#111b27',stroke:'#aebac9','stroke-width':2},g);const horizontal=l.id==='2';const text=el('text',{x:horizontal?x+5:x+(i>12?-18:18),y:name==='人民广场'?y+23:horizontal?y-24:y+5,'text-anchor':horizontal?'start':i>12?'end':'start',...(horizontal?{transform:`rotate(-50 ${x+5} ${y-24})`}:{})},g);text.textContent=name;g.addEventListener('click',()=>select(name));g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select(name);}});nodes.set(name,{g,circle,x,y});}}
$('station').innerHTML=stations.map(s=>`<option>${s}</option>`).join('');$('station').value='人民广场';
function selectedDate(){return night&&minute>=1440?dateShift(date,1):date;}
function info(l,i,d){return directionInfo(l.id,i,d,selectedDate(),minute%1440);}
function select(name,pan=false){$('station').value=name;renderDetail();if(pan){const p=nodes.get(name);$('map-scroll').scrollTo({left:Math.max(0,p.x*zoom-$('map-scroll').clientWidth/2),top:Math.max(0,p.y*zoom-$('map-scroll').clientHeight/2),behavior:'auto'});}}
function renderDetail(){const name=$('station').value;let html=`<h2>${name}</h2>`;for(const l of lines){const i=l.names.indexOf(name);if(i<0)continue;for(const d of [1,-1]){if(i+d<0||i+d>=l.names.length)continue;const s=info(l,i,d);html+=`<div class="direction"><strong style="color:${l.color}">${l.id} 号线 · ${d===1?(l.id==='1'?'北行':'东行'):(l.id==='1'?'南行':'西行')} → ${l.names[i+d]}</strong><div class="status ${s.state}">${s.state==='open'?'●':'○'} ${s.reason}${s.remaining!==null&&s.remaining<=30?` · 距末班 ${s.remaining} 分钟`:''}</div><dl><div><dt>首班</dt><dd>${serviceTime(s.first)}</dd></div><div><dt>最后可上车</dt><dd>${serviceTime(s.last)}</dd></div><div><dt>${s.extraOnly?'加班车终点':'常规末班终点'}</dt><dd>${s.extraOnly?'龙阳路':s.destination}</dd></div></dl>${s.carry?'<p class="note">延续 '+s.date+' 的运营服务</p>':''}${s.notes.map(n=>`<p class="note">${n}</p>`).join('')}</div>`;}}$('detail').innerHTML=html;for(const [n,v]of nodes)v.circle.setAttribute('stroke',n===name?'#e7f5b1':'#9caabd');}
function render(){const t=timeLabel(minute);$('clock').textContent=t;$('selected-time').textContent=(minute>=1440?'次日 ':'')+t;$('mode').textContent=live?'上海当前时间 · 按官方时刻表':playing?'时间播放 · 2 分钟 / 帧':'时间回看 · '+selectedDate();$('slider').value=minute;$('slider').setAttribute('aria-valuetext',t);$('time-input').value=t;$('date').value=date;$('calendar-note').textContent=`${date} · ${extended(date)?'1 号线延时运营日':'常规运营日'}${night?' · 21:00—次日 02:00':''}`;let open=0;for(const e of edges){const s=info(e.l,e.source,e.d),color=s.state==='open'?s.extraOnly?'#efc777':e.l.color:'#465264';if(s.state==='open')open++;e.g.dataset.state=s.state;e.g.dataset.extra=String(s.extraOnly);e.path.setAttribute('stroke',color);e.arrow.setAttribute('stroke',color);e.path.setAttribute('stroke-dasharray',s.extraOnly?'5 5':'none');}for(const [name,n]of nodes){const available=edges.some(e=>e.l.names[e.source]===name&&e.g.dataset.state==='open');n.circle.setAttribute('fill',available?'#182735':'#465264');} $('count').textContent=`${open} / ${edges.length} 个乘车方向仍有服务`;renderDetail();}
function stop(){playing=false;$('play').textContent='▶ 播放';}function setTime(n){stop();live=false;minute=n;render();}
function setRange(value){night=value;$('slider').min=night?1260:0;$('slider').max=night?1560:1439;$('range').textContent=night?'切回全天':'放大夜间';$('ticks').innerHTML=(night?['21:00','22:00','23:00','次日 00:00','01:00','02:00']:['00:00','06:00','12:00','18:00','23:59']).map(t=>`<span>${t}</span>`).join('');}
$('slider').addEventListener('input',e=>setTime(Number(e.target.value)));$('time-input').addEventListener('change',e=>{if(!e.target.value)return;const [h,m]=e.target.value.split(':').map(Number);setRange(false);setTime(h*60+m);});$('station').addEventListener('change',()=>select($('station').value,true));$('date').onchange=()=>{if(!$('date').value)return;date=$('date').value;live=false;stop();render();};$('now').onclick=()=>{stop();live=true;date=todayShanghai();setRange(false);minute=shanghaiMinute();render();};$('play').onclick=()=>{playing=!playing;live=false;if(playing&&minute>=Number($('slider').max))minute=Number($('slider').min);$('play').textContent=playing?'Ⅱ 暂停':'▶ 播放';render();};$('range').onclick=()=>{stop();live=false;setRange(!night);minute=night?Math.max(1260,minute):minute%1440;render();};document.querySelectorAll('[data-time]').forEach(b=>b.onclick=()=>{setRange(false);setTime(Number(b.dataset.time));});setInterval(()=>{if(playing){minute+=2;if(minute>=Number($('slider').max)){minute=Number($('slider').max);stop();}render();}else if(live){const now=shanghaiMinute();if(now!==minute||date!==todayShanghai()){minute=now;date=todayShanghai();render();}}},200);
function scale(){ $('map').style.width=`${1660*zoom}px`;$('map').style.height=`${1240*zoom}px`;}$('plus').onclick=()=>{zoom=Math.min(1.5,zoom+.15);scale();};$('minus').onclick=()=>{zoom=Math.max(.35,zoom-.15);scale();};$('fit').onclick=()=>{zoom=Math.min($('map-scroll').clientWidth/1660,$('map-scroll').clientHeight/1240);scale();$('map-scroll').scrollTo({left:0,top:0});};$('readable').onclick=()=>{zoom=.9;scale();select($('station').value,true);};setRange(false);scale();render();$('readable').click();

let drag=null;const scroller=$('map-scroll');scroller.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'){drag={x:e.clientX,y:e.clientY,left:scroller.scrollLeft,top:scroller.scrollTop,moved:false};}});scroller.addEventListener('pointermove',e=>{if(!drag||!e.buttons)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>5)drag.moved=true;if(drag.moved){scroller.scrollLeft=drag.left-dx;scroller.scrollTop=drag.top-dy;e.preventDefault();}});scroller.addEventListener('click',e=>{if(drag?.moved){e.preventDefault();e.stopPropagation();}drag=null;},true);window.addEventListener('pointerup',()=>{setTimeout(()=>drag=null,0);});
